// Generated by authoring/talks/make_ts.py from authoring/talks/talks.json — edit the JSON, not this file.
export const TALK_TEXTS:Record<string,{title:string;text:string}>={
 "thich-ca":{title:"Đức Phật Thích Ca Mâu Ni",text:"Đức Phật Thích Ca Mâu Ni, tên thật là Tất Đạt Đa, vốn là thái tử nước Ca Tỳ La Vệ, ra đời cách đây hơn hai nghìn sáu trăm năm. Thấy cảnh sinh, già, bệnh, chết của con người, Ngài từ bỏ ngai vàng đi tìm con đường giải thoát. Sau bốn mươi chín ngày thiền định dưới cội bồ đề, Ngài giác ngộ, thành bậc Chánh Đẳng Chánh Giác. Suốt bốn mươi lăm năm, Ngài giảng dạy Tứ Diệu Đế và Bát Chánh Đạo, chỉ cho chúng sinh con đường thoát khổ. Ngài là đức Bổn Sư của chúng ta trong cõi Ta Bà này."},
 "a-di-da":{title:"Đức Phật A Di Đà",text:"Đức Phật A Di Đà là giáo chủ cõi Tây Phương Cực Lạc. Theo kinh Vô Lượng Thọ, khi còn là Tỳ kheo Pháp Tạng, Ngài phát bốn mươi tám đại nguyện, nguyện tạo dựng một cõi nước thanh tịnh, không còn khổ đau, để đón nhận chúng sinh. Danh hiệu Ngài có nghĩa là Vô Lượng Quang và Vô Lượng Thọ, ánh sáng và thọ mạng không thể đo lường. Người thành tâm niệm Nam Mô A Di Đà Phật, giữ tâm hiền thiện, sẽ được Ngài tiếp dẫn về cõi an lành."},
 "di-lac":{title:"Đức Phật Di Lặc",text:"Đức Di Lặc là vị Phật tương lai, hiện ở cung trời Đâu Suất, sẽ hạ sinh thành Phật kế tiếp sau Đức Thích Ca. Tên Ngài có nghĩa là Từ Thị, tức lòng từ rộng lớn. Hình tượng Phật Di Lặc với nụ cười hoan hỷ và chiếc bụng tròn nhắc chúng ta sống bao dung, vui vẻ, biết buông bỏ ưu phiền. Người xưa có câu: bụng to chứa được những chuyện khó chứa trong thiên hạ, miệng cười cười những người đáng cười trong đời."},
 "quan-am":{title:"Bồ Tát Quán Thế Âm",text:"Bồ Tát Quán Thế Âm là hiện thân của lòng đại bi. Tên Ngài có nghĩa là lắng nghe tiếng kêu than của chúng sinh trong cõi đời để đến cứu khổ. Theo phẩm Phổ Môn trong kinh Pháp Hoa, Ngài có thể hiện ra muôn hình tướng để cứu độ, ai gặp nạn mà thành tâm niệm danh hiệu Ngài đều được che chở. Tay Ngài cầm bình nước cam lồ và cành dương liễu, tượng trưng cho sự tưới mát mọi khổ đau. Học hạnh Quán Âm là biết lắng nghe và thương yêu mọi người."},
 "thien-thu-quan-am":{title:"Thiên Thủ Thiên Nhãn Quán Âm",text:"Thiên Thủ Thiên Nhãn Đại Bi Quán Âm là hình tướng nghìn tay nghìn mắt của Bồ Tát Quán Thế Âm. Nghìn mắt để thấy hết nỗi khổ của chúng sinh, nghìn tay để kịp cứu giúp khắp nơi. Hình tướng này gắn với Chú Đại Bi, bài chú quen thuộc trong các khóa lễ. Ngài phát nguyện vì lợi ích và an vui của tất cả chúng sinh. Mỗi bàn tay của Ngài cầm một pháp khí, nhắc chúng ta rằng lòng từ bi cần đi cùng trí tuệ và những việc làm cụ thể."},
 "dai-the-chi":{title:"Bồ Tát Đại Thế Chí",text:"Bồ Tát Đại Thế Chí cùng Bồ Tát Quán Thế Âm đứng hai bên Đức Phật A Di Đà, hợp thành Tây Phương Tam Thánh. Nếu Quán Âm tiêu biểu cho lòng từ bi, thì Đại Thế Chí tiêu biểu cho trí tuệ. Ánh sáng trí tuệ của Ngài soi khắp mọi nơi, giúp chúng sinh thoát khỏi khổ đau. Theo kinh Thủ Lăng Nghiêm, Ngài dạy pháp niệm Phật: nhiếp cả sáu căn, tịnh niệm nối tiếp, nhớ Phật như con nhớ mẹ, thì hiện tại hay mai sau chắc chắn thấy Phật."},
 "van-thu":{title:"Bồ Tát Văn Thù Sư Lợi",text:"Bồ Tát Văn Thù Sư Lợi là vị Bồ Tát tiêu biểu cho đại trí tuệ. Ngài thường được tạc cưỡi sư tử xanh, tay cầm kiếm báu và kinh sách. Thanh kiếm tượng trưng cho trí tuệ chặt đứt phiền não và vô minh, còn sư tử tượng trưng cho sự dũng mãnh của chánh pháp. Ngài thường đứng bên trái Đức Phật Thích Ca. Người học Phật cầu Văn Thù là cầu sự sáng suốt, hiểu đúng lẽ thật, để không bị mê lầm dẫn dắt trong cuộc sống."},
 "pho-hien":{title:"Bồ Tát Phổ Hiền",text:"Bồ Tát Phổ Hiền là vị Bồ Tát tiêu biểu cho đại hạnh, tức là đem lời Phật dạy vào việc làm. Ngài thường cưỡi voi trắng sáu ngà, tượng trưng cho sức mạnh vững chãi và sáu pháp ba la mật. Ngài đứng bên phải Đức Phật Thích Ca, cùng Văn Thù hợp thành Hoa Nghiêm Tam Thánh. Ngài phát mười đại nguyện, như lễ kính chư Phật, tùy hỷ công đức, hằng thuận chúng sinh. Học hạnh Phổ Hiền là hiểu đạo phải đi đôi với thực hành."},
 "dia-tang":{title:"Bồ Tát Địa Tạng Vương",text:"Bồ Tát Địa Tạng Vương là vị Bồ Tát của đại nguyện. Ngài phát lời thề: địa ngục chưa trống, thề không thành Phật; chúng sinh độ hết, mới chứng Bồ đề. Ngài thường được tạc trong hình tướng một vị sư, tay cầm tích trượng để mở cửa địa ngục và viên minh châu soi sáng bóng tối. Kinh Địa Tạng dạy nhiều về đạo hiếu, nên Ngài gắn liền với việc cầu siêu cho ông bà cha mẹ. Học hạnh Địa Tạng là kiên nhẫn và không bỏ rơi ai."},
 "kim-cang-thu":{title:"Bồ Tát Kim Cang Thủ",text:"Kim Cang Thủ Bồ Tát có nghĩa là vị Bồ Tát cầm chày kim cang. Chày kim cang tượng trưng cho trí tuệ vững chắc, phá tan mọi phiền não mà không gì phá được. Ngài là vị hộ trì chánh pháp, bảo vệ người tu hành, và tiêu biểu cho sức mạnh của chư Phật. Trong nhiều truyền thống, Ngài cùng Quán Âm và Văn Thù là ba vị Bồ Tát tượng trưng cho sức mạnh, từ bi và trí tuệ. Học hạnh Ngài là giữ tâm kiên cố trước mọi thử thách."},
 "hu-khong-tang":{title:"Bồ Tát Hư Không Tạng",text:"Bồ Tát Hư Không Tạng có nghĩa là kho báu rộng lớn như hư không. Ngài tiêu biểu cho phước đức và trí tuệ vô tận, có thể ban cho chúng sinh những điều lợi lạc mà không bao giờ cạn. Hư không thì bao dung tất cả, không chướng ngại, vì vậy Ngài dạy chúng ta mở rộng tấm lòng, biết chia sẻ, và thành tâm sám hối lỗi lầm để tâm được trong sáng. Ngài là một trong tám vị đại Bồ Tát thường được tôn thờ."},
 "tru-cai-chuong":{title:"Bồ Tát Trừ Cái Chướng",text:"Bồ Tát Trừ Cái Chướng là vị Bồ Tát giúp chúng sinh dẹp bỏ những ngăn che của tâm. Kinh dạy có năm thứ ngăn che làm tâm không sáng: tham dục, sân hận, hôn trầm, trạo cử và hoài nghi. Khi những ngăn che này được dẹp bỏ, trí tuệ tự nhiên hiển lộ như vầng trăng ra khỏi đám mây. Ngài là một trong tám vị đại Bồ Tát. Học hạnh Ngài là mỗi ngày tự soi lại tâm mình, nhận ra và buông bỏ những điều che lấp."},
 "vo-tan-y":{title:"Bồ Tát Vô Tận Ý",text:"Bồ Tát Vô Tận Ý có nghĩa là tâm ý rộng lớn không cùng tận. Trong phẩm Phổ Môn kinh Pháp Hoa, chính Ngài thưa hỏi Đức Phật vì sao có danh hiệu Quán Thế Âm, rồi cởi chuỗi ngọc quý dâng cúng Bồ Tát Quán Âm. Ngài tiêu biểu cho tâm phát nguyện không bao giờ mệt mỏi, cứu giúp chúng sinh không có giới hạn. Học hạnh Ngài là giữ cho lòng tốt của mình không vơi cạn, dù làm việc thiện nhỏ hay lớn."},
 "duoc-su":{title:"Đức Phật Dược Sư",text:"Đức Phật Dược Sư Lưu Ly Quang là giáo chủ cõi Tịnh Lưu Ly ở phương Đông. Danh hiệu Ngài có nghĩa là vị thầy thuốc chữa lành mọi bệnh khổ, cả bệnh nơi thân lẫn bệnh nơi tâm. Ngài phát mười hai đại nguyện, nguyện cho chúng sinh được khỏe mạnh, đầy đủ, thoát khỏi tai nạn và tà kiến. Tay Ngài thường cầm bình thuốc. Người ta thường tụng kinh Dược Sư để cầu bình an và sức khỏe cho mình và người thân."},
 "ty-lo-gia-na":{title:"Đức Phật Tỳ Lô Giá Na",text:"Đức Phật Tỳ Lô Giá Na có nghĩa là ánh sáng chiếu khắp mọi nơi. Ngài là Pháp thân Phật, tức chân lý thường hằng hiện hữu khắp vũ trụ, và là vị Phật chính của kinh Hoa Nghiêm. Kinh dạy rằng trong một hạt bụi có cả thế giới, mọi sự vật đều liên hệ với nhau như những viên ngọc trên lưới trời Đế Thích phản chiếu lẫn nhau. Hiểu về Ngài là hiểu rằng tánh giác sáng suốt vốn có sẵn nơi mỗi chúng ta."},
 "dai-nhat":{title:"Đại Nhật Như Lai",text:"Đại Nhật Như Lai là danh hiệu của Đức Phật Tỳ Lô Giá Na trong Mật tông, có nghĩa là mặt trời lớn. Mặt trời thường chiếu sáng một nửa thế gian, còn trí tuệ Phật thì soi rọi khắp pháp giới, không phân biệt ngày đêm. Ngài là trung tâm của hai mạn đà la Kim Cang Giới và Thai Tạng Giới, tiêu biểu cho trí tuệ và lòng từ bao trùm vạn vật. Hình tượng Ngài thường đội mão báu, nhắc rằng Phật tánh quý báu ở ngay trong tâm."},
 "a-suc-be":{title:"Đức Phật A Súc Bệ",text:"Đức Phật A Súc Bệ là giáo chủ cõi Diệu Hỷ ở phương Đông. Tên Ngài có nghĩa là Bất Động. Khi còn tu hạnh Bồ Tát, Ngài phát nguyện không bao giờ khởi tâm sân hận với bất kỳ chúng sinh nào, và đã giữ trọn lời nguyện ấy. Tay phải Ngài chạm đất, chứng minh cho sự kiên định. Học hạnh Ngài là giữ tâm bình tĩnh, không để cơn giận làm lay động, vì một đốm lửa sân có thể thiêu rụi cả rừng công đức."},
 "tu-thien-vuong":{title:"Tứ Đại Thiên Vương",text:"Tứ Đại Thiên Vương là bốn vị hộ pháp canh giữ bốn phương. Phương Đông là Trì Quốc Thiên Vương, giữ gìn đất nước, ôm đàn tỳ bà. Phương Nam là Tăng Trưởng Thiên Vương, giúp thiện căn tăng trưởng, cầm kiếm báu. Phương Tây là Quảng Mục Thiên Vương, mắt rộng nhìn thấu thế gian, cầm rồng. Phương Bắc là Đa Văn Thiên Vương, nghe nhiều học rộng, cầm lọng báu. Bốn vị bảo vệ Phật pháp và che chở những người hiền thiện."},
 "dai-pham-thien":{title:"Đại Phạm Thiên Vương",text:"Đại Phạm Thiên Vương là vị vua cõi trời Phạm Thiên, một trong những vị hộ pháp lớn của Phật giáo. Kinh điển kể rằng sau khi Đức Phật thành đạo, chính Phạm Thiên đã thỉnh cầu Ngài chuyển bánh xe pháp, vì thế gian vẫn còn những người ít bụi trần có thể hiểu đạo. Ngài tiêu biểu cho tâm thanh tịnh với bốn đức từ, bi, hỷ, xả, gọi là Tứ Vô Lượng Tâm, hay bốn Phạm trú."},
 "de-thich":{title:"Đế Thích Thiên",text:"Đế Thích Thiên, còn gọi là Thích Đề Hoàn Nhân, là vua cõi trời Đao Lợi trên đỉnh núi Tu Di. Ngài là vị hộ pháp thường đến nghe Đức Phật giảng pháp và bảo vệ người tu hành. Kinh kể rằng nhờ giữ bảy điều nguyện, như hiếu kính cha mẹ, kính trọng người lớn, nói lời hòa nhã và chân thật, Ngài được sinh làm vua cõi trời. Lưới ngọc trong cung điện Ngài trở thành hình ảnh nổi tiếng về sự liên kết của vạn vật."},
 "ma-loi-chi":{title:"Ma Lợi Chi Thiên",text:"Ma Lợi Chi Thiên là vị thiên nữ hộ pháp, tên Ngài có nghĩa là ánh dương quang, như tia nắng ban mai. Ánh sáng thì ai cũng thấy mà không ai nắm bắt được, nên Ngài thường được cầu nguyện để che chở người đi đường, tránh khỏi tai nạn và kẻ xấu. Hình tượng Ngài có khi ngự trên xe do đàn heo kéo, tượng trưng cho sự nhanh nhẹn vượt qua chướng ngại. Ngài nhắc chúng ta sống sáng suốt và lặng lẽ làm điều tốt."},
 "khong-tuoc-minh-vuong":{title:"Khổng Tước Minh Vương",text:"Khổng Tước Minh Vương là vị hộ pháp ngự trên chim công. Chim công có thể ăn các loài rắn độc mà không hề hấn gì, tượng trưng cho khả năng chuyển hóa tham, sân, si, những chất độc trong tâm, thành trí tuệ. Theo kinh Khổng Tước Minh Vương, thần chú của Ngài giúp trừ bệnh tật, tai ách và mang lại bình an. Dáng vẻ hiền hòa của Ngài nhắc rằng khó khăn trong đời cũng có thể chuyển thành bài học quý."},
 "bien-tai-thien":{title:"Biện Tài Thiên",text:"Biện Tài Thiên là vị thiên nữ hộ pháp của âm nhạc, trí tuệ và tài ăn nói. Ngài thường được tạc cầm đàn tỳ bà. Trong kinh Kim Quang Minh, Ngài phát nguyện ban cho người thuyết pháp tài biện luận trôi chảy, trí nhớ tốt và sự hiểu biết sâu sắc, để giáo pháp được truyền rộng. Học sinh, nghệ sĩ và người làm công việc chữ nghĩa thường cầu nguyện Ngài. Ngài nhắc chúng ta dùng lời nói hay để đem lại lợi ích cho người."},
 "cat-tuong-thien-nu":{title:"Cát Tường Thiên Nữ",text:"Cát Tường Thiên Nữ, còn gọi là Công Đức Thiên, là vị thiên nữ hộ pháp của may mắn và phúc lộc. Trong kinh Kim Quang Minh, Ngài phát nguyện giúp những ai thọ trì kinh điển được đầy đủ vật dụng, ruộng vườn tươi tốt, đời sống ấm no. Hình tượng Ngài đoan trang, tay cầm ngọc như ý. Theo lời Phật dạy, phúc lộc chân thật đến từ việc làm thiện, bố thí và sống chân thành, chứ không chỉ từ cầu xin."},
 "phat-khat-thuc":{title:"Tượng Phật khất thực",text:"Tượng Phật khất thực tái hiện hình ảnh Đức Phật ôm bình bát đi xin ăn mỗi buổi sáng. Hạnh khất thực giúp người tu sống giản dị, không tích trữ, bớt đi lòng tham và cái tôi. Đồng thời, đó cũng là dịp để mọi người gieo trồng phước đức qua việc cúng dường. Đức Phật đi khất thực tuần tự từng nhà, không phân biệt giàu nghèo. Hình ảnh này dạy chúng ta sống khiêm cung, biết đủ và biết ơn từng bữa ăn."},
 "bo-tat-tuoi-sen":{title:"Bồ Tát tưới sen",text:"Hình tượng Bồ Tát tưới sen tượng trưng cho việc vun bồi hạt giống lành trong tâm. Hoa sen mọc lên từ bùn mà không nhiễm mùi bùn, cũng như tâm thanh tịnh có thể nở hoa ngay giữa cuộc đời nhiều phiền não. Nước cam lồ Bồ Tát tưới là lời dạy từ bi và trí tuệ. Mỗi ngày làm một việc tốt, nói một lời hay, giữ một ý thiện, chính là đang tưới cho đóa sen trong lòng mình nở hoa."},
 "ho-phap-bat-bo":{title:"Hai mươi tám bộ chúng hộ pháp",text:"Các vị hộ pháp đứng hai bên lối đi thuộc Nhị Thập Bát Bộ Chúng, tức hai mươi tám bộ chúng thần hộ trì những người trì tụng Chú Đại Bi. Trong đó có Mật Tích Kim Cang Sĩ, Phạm Thiên, Đế Thích, Khổng Tước Vương và nhiều vị thần khác từ các cõi trời, cõi người. Các vị phát nguyện bảo vệ chánh pháp và người tu thiện. Đi giữa hai hàng hộ pháp, chúng ta nhớ rằng giữ tâm lành thì luôn được che chở."}
};
